<script>document.querySelectorAll('.career-tab').forEach(tab=>tab.addEventListener('click',()=>{document.querySelectorAll('.career-tab').forEach(item=>{item.classList.toggle('active',item===tab);item.setAttribute('aria-selected',String(item===tab));});document.querySelectorAll('.career-panel').forEach(panel=>panel.classList.toggle('active',panel.id===tab.dataset.panel));}));const modal=document.getElementById('application-modal');document.querySelectorAll('[data-opening]').forEach(b=>b.onclick=()=>{modal.style.display='flex';document.getElementById('application-opening').value=b.dataset.opening;document.getElementById('application-role').textContent=b.dataset.opening;});document.getElementById('close-application').onclick=()=>modal.style.display='none';</script>
